∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {T : Breakdown.CertCell.TreeEntry D R} {e : ℝ}
  {Y : Breakdown.CertCell.CellLayerEntries D R T},
  Breakdown.CertCell.CellLayerEntryConditions D R T e Y →
    Breakdown.CertCell.PotentialEntryConditions D R Y.assembly Y.coupling
      (Breakdown.CertCell.Assembly.InRowRange Y.rows)

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM} {cForm : ℝ} {q : Fin k → ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space} {κ : Fin k → ℝ} {F : ℝ → Breakdown.Space → Breakdown.Space}
  {perturbation : Breakdown.IsPerturbation D.cert.symmetries (D.cert.period q) v G H g}
  {right_measurable : MeasureTheory.AEStronglyMeasurable (fun z => F z.1 z.2) MeasureTheory.volume}
  {right_periodic : Breakdown.IsTimePeriodic F} {right_finite : (Breakdown.periodLIntegral fun σ y => ‖F σ y‖ ^ 2) < ⊤}
  {right_side : Breakdown.IsRightSide (D.cert.model q) D.cert.actuator κ v G g F}
  {pos_finite : (D.withFormCoercivity cForm).formPos q v G H < ⊤} {v_1 : ℝ → Breakdown.Space → Breakdown.Space}
  {G_1 : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H_1 : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g_1 : ℝ → Breakdown.Space → Breakdown.Space} {κ_1 : Fin k → ℝ} {F_1 : ℝ → Breakdown.Space → Breakdown.Space}
  {perturbation_1 : Breakdown.IsPerturbation D.cert.symmetries (D.cert.period q) v_1 G_1 H_1 g_1}
  {right_measurable_1 : MeasureTheory.AEStronglyMeasurable (fun z => F_1 z.1 z.2) MeasureTheory.volume}
  {right_periodic_1 : Breakdown.IsTimePeriodic F_1}
  {right_finite_1 : (Breakdown.periodLIntegral fun σ y => ‖F_1 σ y‖ ^ 2) < ⊤}
  {right_side_1 : Breakdown.IsRightSide (D.cert.model q) D.cert.actuator κ_1 v_1 G_1 g_1 F_1}
  {pos_finite_1 : (D.withFormCoercivity cForm).formPos q v_1 G_1 H_1 < ⊤},
  { v := v, G := G, H := H, g := g, κ := κ, F := F, perturbation := perturbation, right_measurable := right_measurable,
        right_periodic := right_periodic, right_finite := right_finite, right_side := right_side,
        pos_finite := pos_finite } =
      { v := v_1, G := G_1, H := H_1, g := g_1, κ := κ_1, F := F_1, perturbation := perturbation_1,
        right_measurable := right_measurable_1, right_periodic := right_periodic_1, right_finite := right_finite_1,
        right_side := right_side_1, pos_finite := pos_finite_1 } →
    v = v_1 ∧ G = G_1 ∧ H = H_1 ∧ g = g_1 ∧ κ = κ_1 ∧ F = F_1

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S →
    ∀ (j : Fin R.creditCount) (K : Fin D.mesh.count) (ι : ℤ × ℤ),
      Breakdown.CertCell.labelHarmonic D.azimuthOrder ι = Breakdown.CertCell.flipLabel (R.creditPatch j).label ∨
          Breakdown.CertCell.labelHarmonic D.azimuthOrder ι = -Breakdown.CertCell.flipLabel (R.creditPatch j).label →
        ι ∉ D.mesh.resolved K ∧ ι ∉ D.mesh.band K

∀ {C : Type} {nE nM : ℕ} {chart : Breakdown.CellCert.GivenFields.ChartParams} {centralRadius : ℝ} {classOf : ℤ × ℤ → C}
  {strainWeight vorticityWeight : C → Breakdown.CertCell.Instance.ChartScalar}
  {eps : Fin nE → Breakdown.CertCell.Instance.EpsGiven} {mu : Fin nM → Breakdown.CertCell.Instance.MuGiven} {c cμ : ℝ}
  {chart_1 : Breakdown.CellCert.GivenFields.ChartParams} {centralRadius_1 : ℝ} {classOf_1 : ℤ × ℤ → C}
  {strainWeight_1 vorticityWeight_1 : C → Breakdown.CertCell.Instance.ChartScalar}
  {eps_1 : Fin nE → Breakdown.CertCell.Instance.EpsGiven} {mu_1 : Fin nM → Breakdown.CertCell.Instance.MuGiven}
  {c_1 cμ_1 : ℝ},
  { chart := chart, centralRadius := centralRadius, classOf := classOf, strainWeight := strainWeight,
        vorticityWeight := vorticityWeight, eps := eps, mu := mu, c := c, cμ := cμ } =
      { chart := chart_1, centralRadius := centralRadius_1, classOf := classOf_1, strainWeight := strainWeight_1,
        vorticityWeight := vorticityWeight_1, eps := eps_1, mu := mu_1, c := c_1, cμ := cμ_1 } →
    chart = chart_1 ∧
      centralRadius = centralRadius_1 ∧
        classOf = classOf_1 ∧
          strainWeight = strainWeight_1 ∧
            vorticityWeight = vorticityWeight_1 ∧ eps = eps_1 ∧ mu = mu_1 ∧ c = c_1 ∧ cμ = cμ_1

∀ {K : Breakdown.CellCert.CellAnalysis.CellBox} {resolved : Finset (ℤ × ℤ)}
  {coef : ℤ × ℤ → ℝ × ℝ → Breakdown.CertCell.ModeCoefficients} {ch : Breakdown.CertCell.ModeCharges}
  {T : Breakdown.CertCell.CellCalculus.LeafValues},
  Breakdown.CertCell.CellCalculus.IsLeafValues K resolved coef ch T → ∀ ι ∈ resolved, 0 ≤ T.curlHessFloor ι

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CellReduction.Instantiation.ProfileShapeEntry k}
  {Pr : Breakdown.CellReduction.Instantiation.PressureShapeEntry k},
  Breakdown.CellReduction.Instantiation.IsPressureShapeEntry D R Pr →
    ∀ (q : Fin k → ℝ) (σ : ℝ) (y : Breakdown.Space),
      D.cert.pressureGrad q σ y = gradient (fun y' => Pr.pressure R q σ y' - ‖D.cert.profile q σ y'‖ ^ 2 / 2) y

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM} {cForm : ℝ} {q : Fin k → ℝ}
  (self : Breakdown.CertCell.AdmissibleTuple D cForm q),
  Breakdown.IsPerturbation D.cert.symmetries (D.cert.period q) self.v self.G self.H self.g

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S →
    ∀ (K : Fin D.mesh.count), 0 ≤ (P.potential K).epsStrain ∧ 0 ≤ (P.potential K).epsGrad

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {epsSup epsGradSup ratio : ℝ},
  Breakdown.CertCell.InstanceSplit.EnclosureAdmissibleClauses m P h W HW epsSup epsGradSup ratio →
    ∀ β ∈ h.harmonics, ∀ (σ : ℝ) (y : Breakdown.Space), √(Breakdown.cnormSq (Breakdown.modeVel β W σ y)) ≤ h.ampW β y

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {epsSup epsGradSup ratio : ℝ},
  Breakdown.CertCell.InstanceSplit.EnclosureAdmissibleClauses m P h W HW epsSup epsGradSup ratio →
    ∀ (σ φ : ℝ) (y : Breakdown.Space), ‖Breakdown.curlVec (fderiv ℝ (W σ) (Breakdown.axialRot φ y))‖ ≤ h.supVort y

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {X : Breakdown.CertCell.Instance.InstanceData k C nE nM} {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D}
  {T : Breakdown.CertCell.TreeEntry D R} {Y : Breakdown.CertCell.CellLayerEntries D R T}
  {N : Breakdown.CellLayerSystem.CoerciveNumbers} {B : Breakdown.CellLayerSystem.ReductionEntries k},
  Breakdown.CellLayerSystem.CellSystemCondition D X R T Y N B →
    Breakdown.CertReduction.AdjointQuadraticBounded D.cert B.adjointQuad

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S →
    ∀ (j : Fin R.creditCount),
      Breakdown.CertCell.IsLatticeHarmonic D.azimuthOrder (Breakdown.CertCell.flipLabel (R.creditPatch j).label)

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S → Breakdown.CertCell.Assembly.EntryChargesRegular D R

∀ {label : ℤ × ℤ} {inner outer height : ℝ} {charge : ℝ × ℝ → ℝ} {chargeLower chargeUpper : ℝ} {testCount : ℕ}
  {test : Fin testCount → ℝ × ℝ → ℝ} {testSlope : NNReal} {testForm : Matrix (Fin testCount) (Fin testCount) ℝ}
  {segmentCount : ℕ} {segment : Fin segmentCount → Breakdown.CertCell.Bridge.PlaneSegment} {dataCount : ℕ}
  {dataOf : Fin dataCount → (s : Fin segmentCount) × Fin (segment s).testCount}
  {traceMap : Matrix (Fin testCount) (Fin dataCount) ℝ} {credit : Matrix (Fin dataCount) (Fin dataCount) ℂ}
  {label_1 : ℤ × ℤ} {inner_1 outer_1 height_1 : ℝ} {charge_1 : ℝ × ℝ → ℝ} {chargeLower_1 chargeUpper_1 : ℝ}
  {testCount_1 : ℕ} {test_1 : Fin testCount_1 → ℝ × ℝ → ℝ} {testSlope_1 : NNReal}
  {testForm_1 : Matrix (Fin testCount_1) (Fin testCount_1) ℝ} {segmentCount_1 : ℕ}
  {segment_1 : Fin segmentCount_1 → Breakdown.CertCell.Bridge.PlaneSegment} {dataCount_1 : ℕ}
  {dataOf_1 : Fin dataCount_1 → (s : Fin segmentCount_1) × Fin (segment_1 s).testCount}
  {traceMap_1 : Matrix (Fin testCount_1) (Fin dataCount_1) ℝ} {credit_1 : Matrix (Fin dataCount_1) (Fin dataCount_1) ℂ},
  { label := label, inner := inner, outer := outer, height := height, charge := charge, chargeLower := chargeLower,
        chargeUpper := chargeUpper, testCount := testCount, test := test, testSlope := testSlope, testForm := testForm,
        segmentCount := segmentCount, segment := segment, dataCount := dataCount, dataOf := dataOf,
        traceMap := traceMap, credit := credit } =
      { label := label_1, inner := inner_1, outer := outer_1, height := height_1, charge := charge_1,
        chargeLower := chargeLower_1, chargeUpper := chargeUpper_1, testCount := testCount_1, test := test_1,
        testSlope := testSlope_1, testForm := testForm_1, segmentCount := segmentCount_1, segment := segment_1,
        dataCount := dataCount_1, dataOf := dataOf_1, traceMap := traceMap_1, credit := credit_1 } →
    label = label_1 ∧
      inner = inner_1 ∧
        outer = outer_1 ∧
          height = height_1 ∧
            charge = charge_1 ∧
              chargeLower = chargeLower_1 ∧
                chargeUpper = chargeUpper_1 ∧
                  testCount = testCount_1 ∧
                    test ≍ test_1 ∧
                      testSlope = testSlope_1 ∧
                        testForm ≍ testForm_1 ∧
                          segmentCount = segmentCount_1 ∧
                            segment ≍ segment_1 ∧
                              dataCount = dataCount_1 ∧ dataOf ≍ dataOf_1 ∧ traceMap ≍ traceMap_1 ∧ credit ≍ credit_1

∀ {count : ℕ} {box : Fin count → Breakdown.CellCert.CellAnalysis.CellBox} {m : ℕ} {K : Fin count} {deg : ℕ}
  {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {model : Breakdown.CertCell.ModelPolys count} {err : Breakdown.CertCell.ModelErrors}
  {high : Breakdown.CertCell.CellCalculus.CellModelHigh} {long : Breakdown.CertCell.CellCalculus.CellModelLong},
  Breakdown.CertCell.CellCalculus.IsCellModelSplit box m K deg W HW model err high long →
    Breakdown.CertCell.CellCalculus.IsSplitPart (Breakdown.CertCell.CellCalculus.ownSolid box K) W
      (model.velocity.field box m) high.velocity long.velocity err.velocityHigh long.errVelocity err.velocity

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S → Breakdown.CertCell.CellCalculus.CellCalculusConditions D R

∀ {A B : Type} [inst : Fintype A] [inst_1 : Fintype B] {T : Breakdown.CertCell.Certificate.SignedTree A B} {ν : T.Node}
  {D : Breakdown.CertCell.Certificate.RealNodeData A B} {E F : Matrix (A ⊕ B) (A ⊕ B) ℝ},
  Breakdown.CertCell.Certificate.PassesRealNodeEnclosure T ν D E F → D.base.transpose = D.base

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.RowFunctionalConditions D R A P S →
    ∀ (K : Fin D.mesh.count), ∀ ι ∈ R.pairSlackLabels K, 0 < R.pairSlackWeight K ι

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {X : Breakdown.CertCell.Instance.InstanceData k C nE nM} {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D}
  {T : Breakdown.CertCell.TreeEntry D R} {e : ℝ},
  Breakdown.CertCell.CellHypothesis D X R T e →
    ∃ ePair,
      Breakdown.CertCell.InstancePair.IsPairSurrogate D R X.actuatorModes ePair ∧ ∑ K, R.kappaCost K + ∑ K, ePair K ≤ e

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D}
  {potential :
    (K : Fin D.mesh.count) → Breakdown.CertCell.Assembly.PotentialData (Breakdown.CertCell.Assembly.CellVars D R K)}
  {pairing : Fin D.mesh.count → Breakdown.CertCell.Assembly.PairingData k}
  {potential_1 :
    (K : Fin D.mesh.count) → Breakdown.CertCell.Assembly.PotentialData (Breakdown.CertCell.Assembly.CellVars D R K)}
  {pairing_1 : Fin D.mesh.count → Breakdown.CertCell.Assembly.PairingData k},
  { potential := potential, pairing := pairing } = { potential := potential_1, pairing := pairing_1 } →
    potential = potential_1 ∧ pairing = pairing_1

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.RowFunctionalConditions D R A P S →
    ∀ (K : Fin D.mesh.count), 0 < (A.blocks K).actuatorCost ∧ 0 ≤ (A.blocks K).actuatorErr

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {X : Breakdown.CertCell.Instance.InstanceData k C nE nM} {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D}
  {T : Breakdown.CertCell.TreeEntry D R} {e : ℝ},
  Breakdown.CertCell.CellHypothesis D X R T e → ∀ (K : Fin D.mesh.count), 0 ≤ R.kappaCost K

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {Q : Fin D.mesh.count → Breakdown.CertCell.Assembly.PairingData k}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PairingConditions D R A Q S →
    ∀ (K : Fin D.mesh.count) (x : Breakdown.CertCell.Assembly.CellVars D R K → ℂ),
      S K x →
        Breakdown.CellCert.CellFormula.quadFormValue (A.blocks K).pairingKept x ≤
          Breakdown.CertCell.Assembly.pairingExact D R K (Q K) x

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {P : Breakdown.CellReduction.Instantiation.ProfileShapeEntry k} {N : Breakdown.CellLayerSystem.ShiftNumbers},
  Breakdown.CellLayerSystem.ShiftNumbersBounded D P N → 0 ≤ N.boxGrad

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g → ∀ᵐ (σ : ℝ), ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (‖v σ y‖ ^ 6) < ⊤

∀ {m : ℕ} {K : Breakdown.CellCert.CellAnalysis.CellBox} {resolved tested : Finset (ℤ × ℤ)}
  {err : Breakdown.CertCell.ModelErrors} {bc : Breakdown.CertCell.CellCalculus.BoxConstants}
  {ch : Breakdown.CertCell.ModeCharges} {T : Breakdown.CertCell.CellCalculus.LeafValues},
  Breakdown.CertCell.CellCalculus.IsLeafBoxLink m K resolved tested err bc ch T →
    ∀ ι ∈ resolved, ∀ p ∈ K.rect, 3 / (2 * √2) * err.vorticityGrad * bc.secondLength ≤ T.boxPairStrain ι

∀ {count : ℕ} {box : Fin count → Breakdown.CellCert.CellAnalysis.CellBox} {m : ℕ} {K : Fin count} {deg : ℕ}
  {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {model : Breakdown.CertCell.ModelPolys count} {err : Breakdown.CertCell.ModelErrors}
  {high : Breakdown.CertCell.CellCalculus.CellModelHigh} {long : Breakdown.CertCell.CellCalculus.CellModelLong},
  Breakdown.CertCell.CellCalculus.IsCellModelSplit box m K deg W HW model err high long →
    model.velocity.IsConjugateClosed box ∧
      model.vorticity.IsConjugateClosed box ∧
        model.strain.IsConjugateClosed box ∧ model.vorticityGrad.IsConjugateClosed box

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S →
    ∀ (K : Fin D.mesh.count),
      ∀ α ∉ D.model.vorticityGrad.labels K,
        ∀ p ∈ (D.mesh.box K).rect, ∀ (a b : Fin 3), D.model.vorticityGrad.planeValue D.mesh.box K α a b p = 0

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {T : Breakdown.CertCell.TreeEntry D R} {e : ℝ}
  {Y : Breakdown.CertCell.CellLayerEntries D R T},
  Breakdown.CertCell.CellLayerEntryConditions D R T e Y →
    Breakdown.CertCell.Assembly.RowFunctionalConditions D R Y.assembly Y.coupling
      (Breakdown.CertCell.Assembly.InRowRange Y.rows)

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {A : Breakdown.CertCell.Assembly.AssemblyEntry D R}
  {P : Breakdown.CertCell.Assembly.CouplingEntries D R}
  {S : (K : Fin D.mesh.count) → (Breakdown.CertCell.Assembly.CellVars D R K → ℂ) → Prop},
  Breakdown.CertCell.Assembly.PotentialConditions D R A P S → Breakdown.CertCell.IsCellMesh D.mesh

∀ {A B : Type} [inst : Fintype A] [inst_1 : Fintype B] {T : Breakdown.CertCell.Certificate.SignedTree A B} {ν : T.Node}
  {D : Breakdown.CertCell.Certificate.ComplexNodeData A B} {E F : Matrix D.Index D.Index ℝ},
  Breakdown.CertCell.Certificate.PassesComplexNodeEnclosure T ν D E F → F.transpose = F

∀ {rowCount : ℕ} {M : Breakdown.CertCell.CellMesh} {R : Breakdown.CertCell.RowValues M.count rowCount} {m : ℕ}
  {tauMax : ℝ},
  Breakdown.CertCell.Instance.IsRowValues M R m tauMax → ∀ (a : Fin rowCount), R.labelOf a ∈ M.tested (R.cellOf a)

∀ {k : ℕ} {field : ℝ → Breakdown.Space → Breakdown.Space} {pinCoef : Fin k → ℝ}
  {pins : Breakdown.AdjointDefect.PinData k} {centre : (Fin k → ℝ) → ℝ → Breakdown.Space → Breakdown.Space}
  {centrePeriod : ℝ} {periodRate : Fin k → ℝ} {fittedSet : Finset (Fin k)}
  {fitted : Fin k → ℝ → Breakdown.Space → Breakdown.Space}
  {free : (Fin k → ℝ) → Fin k → ℝ → Breakdown.Space → Breakdown.Space}
  {centrePotential : Breakdown.AdjointDefect.PotentialData}
  {fittedPotential : Fin k → Breakdown.AdjointDefect.PotentialData}
